function SWEP:PlaySeq(seq, rate)
    local vm = self:GetOwner():GetViewModel()
    if not IsValid(vm) then return 0 end
    local s = vm:LookupSequence(seq)
    if s and s >= 0 then
        vm:SendViewModelMatchingSequence(s)
        local r = rate or 1
        vm:SetPlaybackRate(r)
        return vm:SequenceDuration(s) / r
    end
    return 0
end

-- Dual wield code (only injected when detected)


-- Sprint code (goes below dual block)
function SWEP:Think()
    if not IsValid(self.Owner) then return end
    local vm = self.Owner:GetViewModel()
    if IsValid(vm) then vm:SetPlaybackRate(1) end

    if self.Owner:KeyDown(IN_SPEED) then
        if not self.Sprinting then
            self.Sprinting = true
            if IsValid(vm) then
                local seq = vm:LookupSequence("sprint_loop")
                if seq and seq >= 0 then
                    vm:SendViewModelMatchingSequence(seq)
                    vm:SetCycle(0)
                    vm:SetPlaybackRate(1)
                end
            end
        end
    else
        if self.Sprinting then
            self.Sprinting = false
            self:PlaySeq("sprint_out", 1)
        end
    end
end
